const shifts = [
  { impact: 0.30, distance: 0.20 },
  { impact: 0.25, distance: 0.16 },
];
const cls = shifts.reduce((sum, s) => sum + s.impact * s.distance, 0);

function band(value, good, poor) {
  if (value <= good) return 'good';
  if (value <= poor) return 'needs-improvement';
  return 'poor';
}

const lcpSeconds = 3.2;
const inpMs = 380;

console.log('CLS=' + cls.toFixed(2) + ' ' + band(cls, 0.1, 0.25));
console.log('LCP=' + lcpSeconds + 's ' + band(lcpSeconds, 2.5, 4.0));
console.log('INP=' + inpMs + 'ms ' + band(inpMs, 200, 500));

